import type { Remote } from './remote'

export const SIZES = ['sm', 'md', 'lg'] as const
export type Size = (typeof SIZES)[number]
export enum Mode { A = 'a', B = 'b' }
type Tone = 'info' | 'warn'

export interface Item<T> { id: T; label: string }

export interface FixProps {
  /** The label. */
  label: string
  /** How big. */
  size?: Size
  tone?: Tone
  variant?: 'solid' | 'outline'
  disabled?: boolean
  onChange?: (value: string, event: React.MouseEvent) => void
  items?: string[]
  list?: Array<Item<number>>
  mode?: Mode
  /** @default 'md' */
  fallback?: Size
  remote?: Remote
  style?: React.CSSProperties
  children?: React.ReactNode
}

/** A fixture. */
export function Fix({ label, size = 'md', variant = 'solid', disabled = false }: FixProps) {
  return <button disabled={disabled}>{label}{size}{variant}</button>
}

