// usage: node run.cjs <file> <tsconfig>
const path = require('node:path')
const base = path.resolve(__dirname, '../../apps/oracle/')
const req = require('node:module').createRequire(base + '/package.json')
const { withCustomConfig } = req('react-docgen-typescript')
const [file, tsconfig] = process.argv.slice(2)
const p = withCustomConfig(tsconfig, { shouldExtractLiteralValuesFromEnum: true, shouldRemoveUndefinedFromOptional: true, propFilter: { skipPropsWithoutDoc: false } })
const docs = p.parse([file])
for (const d of docs) {
  const e = Object.entries(d.props)
  console.log('COMPONENT', d.displayName, 'props', e.length)
  for (const [k, v] of e) {
    const own = !String(v.parent && v.parent.fileName).includes('node_modules')
    if (own || process.env.ALL) console.log(k, JSON.stringify({ type: v.type, required: v.required, defaultValue: v.defaultValue, description: v.description, parent: v.parent, declarations: v.declarations }))
  }
}

