import * as React from 'react'

type Pair = [string, number?]
interface Opt { a: string; b?: number; [k: string]: unknown }
type Key = keyof Opt

export interface ShapesProps<T extends string = 'a'> {
  fn?: (a?: string, ...rest: number[]) => Promise<void>
  tuple?: Pair
  rec?: Record<string, Opt>
  inter?: Opt & { c: boolean }
  keyed?: Key
  gen?: T
  num?: 1 | 2 | 3
  nullable?: string | null
  ro?: readonly string[]
  obj?: { x: number; y?: string }
  ref?: React.Ref<HTMLDivElement>
  as?: React.ElementType
  required: number | undefined
  /** Deprecated. @deprecated use other */
  old?: boolean
}

export function Shapes<T extends string = 'a'>(props: ShapesProps<T>) {
  return <div>{props.gen}</div>
}

