// usage: node dump.mjs <tsconfig> <out.json> <files...>; both tools, full per-prop objects
import { readFileSync, writeFileSync } from 'node:fs'
import { createRequire } from 'node:module'
import { pathToFileURL, fileURLToPath } from 'node:url'
const require = createRequire(fileURLToPath(new URL('../../apps/oracle/package.json', import.meta.url)))
const { withCustomConfig } = require('react-docgen-typescript')
const { parse } = await import(pathToFileURL(require.resolve('react-docgen')).href)
const [tsconfig, out, ...files] = process.argv.slice(2)
const t0 = performance.now()
const rdt = withCustomConfig(tsconfig, { shouldExtractLiteralValuesFromEnum: true, shouldRemoveUndefinedFromOptional: true, propFilter: { skipPropsWithoutDoc: false } }).parse(files)
const t1 = performance.now()
const rdtOut = rdt.map((d) => ({ file: d.filePath, name: d.displayName, props: d.props }))
const rdgOut = []
let failed = 0
for (const f of files) {
  try {
    for (const d of parse(readFileSync(f, 'utf8'), { filename: f })) rdgOut.push({ file: f, name: d.displayName ?? '', props: d.props ?? {} })
  } catch { failed++ }
}
const t2 = performance.now()
writeFileSync(out, JSON.stringify({ rdt: rdtOut, rdg: rdgOut, rdtMs: t1 - t0, rdgMs: t2 - t1, rdgFailed: failed }))

