// SCRATCH, uncommitted: prototype adapters for RDT and react-docgen, scored with the oracle's own compare().
import { readFileSync, realpathSync } from 'node:fs'
import ts from 'typescript'
import { API, SignatureKind, SymbolFlags } from 'typescript-beta/sync'
import { checkerNormalizer } from './oracle-checker.ts'
import { bareName, caliperNorm, compare, prim, type Norm, type Verdict } from './oracle-compare.ts'

const [root, tsconfig, caliperFile, dumpFile, ...files] = process.argv.slice(2)
const K = ts.SyntaxKind

const strip = (s: string) => s.replace(/^['"`]|['"`]$/g, '')
function fromNode(n: ts.TypeNode): Norm {
  switch (n.kind) {
    case K.StringKeyword: return prim('string')
    case K.NumberKeyword: return prim('number')
    case K.BooleanKeyword: return prim('boolean')
    case K.AnyKeyword: return prim('any')
    case K.UnknownKeyword: return prim('unknown')
    case K.NeverKeyword: return prim('never')
    case K.VoidKeyword: return prim('void')
    case K.UndefinedKeyword: return prim('undefined')
    case K.NullKeyword: return prim('null')
    case K.ObjectKeyword: return prim('object')
    case K.LiteralType: {
      const l = (n as ts.LiteralTypeNode).literal
      if (l.kind === K.NullKeyword) return prim('null')
      if (l.kind === K.TrueKeyword) return { k: 'lit', value: 'true' }
      if (l.kind === K.FalseKeyword) return { k: 'lit', value: 'false' }
      return { k: 'lit', value: l.kind === K.PrefixUnaryExpression ? l.getText() : strip(l.getText()) }
    }
    case K.ParenthesizedType: return fromNode((n as ts.ParenthesizedTypeNode).type)
    case K.UnionType: return { k: 'union', members: (n as ts.UnionTypeNode).types.map(fromNode) }
    case K.IntersectionType: return { k: 'intersection', members: (n as ts.IntersectionTypeNode).types.map(fromNode) }
    case K.ArrayType: return { k: 'array', element: fromNode((n as ts.ArrayTypeNode).elementType) }
    case K.TypeOperator: {
      const o = n as ts.TypeOperatorNode
      return o.operator === K.ReadonlyKeyword ? fromNode(o.type) : { k: 'opaque' }
    }
    case K.TupleType: return { k: 'tuple', elements: (n as ts.TupleTypeNode).elements.map((e) => fromNode(ts.isOptionalTypeNode(e) || ts.isRestTypeNode(e) ? e.type : (e as ts.TypeNode))) }
    case K.FunctionType: {
      const f = n as ts.FunctionTypeNode
      return { k: 'function', params: f.parameters.map((p) => ({ optional: !!p.questionToken, rest: !!p.dotDotDotToken, type: p.type ? fromNode(p.type) : prim('any') })), returns: fromNode(f.type) }
    }
    case K.TypeLiteral: {
      const t = n as ts.TypeLiteralNode
      const calls = t.members.filter(ts.isCallSignatureDeclaration)
      if (calls.length === 1 && t.members.length === 1) {
        const f = calls[0]
        return { k: 'function', params: f.parameters.map((p) => ({ optional: !!p.questionToken, rest: !!p.dotDotDotToken, type: p.type ? fromNode(p.type) : prim('any') })), returns: f.type ? fromNode(f.type) : prim('any') }
      }
      return { k: 'object', fields: t.members.filter(ts.isPropertySignature).map((m) => m.name.getText().replace(/^['"]|['"]$/g, '')).toSorted(), index: t.members.some(ts.isIndexSignatureDeclaration) }
    }
    case K.TypeReference: {
      const r = n as ts.TypeReferenceNode
      const name = bareName(r.typeName.getText())
      if ((name === 'Array' || name === 'ReadonlyArray') && r.typeArguments?.length === 1) return { k: 'array', element: fromNode(r.typeArguments[0]) }
      return { k: 'name', name }
    }
    default: return { k: 'opaque' }
  }
}
function fromText(text: string): Norm {
  const sf = ts.createSourceFile('t.ts', `type T = ${text}`, ts.ScriptTarget.ES2022, true)
  const decl = sf.statements[0] as ts.TypeAliasDeclaration
  if (sf.parseDiagnostics?.length) return { k: 'error' }
  return fromNode(decl.type)
}
const rdtNorm = (t: any): Norm | undefined => {
  if (!t) return undefined
  if (t.name === 'enum' && Array.isArray(t.value)) {
    const members: Norm[] = t.value.map((v: any) => ({ k: 'lit', value: strip(v.value) }))
    return members.length === 1 ? members[0] : { k: 'union', members }
  }
  return fromText(t.name)
}
const rdgNorm = (t: any): Norm | undefined => (t ? fromText(t.raw ?? t.name) : undefined)

const api = new API({ cwd: realpathSync(root) })
const { options } = api.parseConfigFile(tsconfig)
const program = api.createProgram(files, options)
const { checker } = program.getProject()
const norm = checkerNormalizer(checker)
const caliper = JSON.parse(readFileSync(caliperFile, 'utf8'))
const dump = JSON.parse(readFileSync(dumpFile, 'utf8'))
const nm = (s: string) => s.replace(/[^A-Za-z0-9]/g, '')
function propsTypeOf(exported: any): any | undefined {
  const symbol = exported.flags & SymbolFlags.Alias ? checker.getAliasedSymbol(exported) : exported
  const type = checker.getTypeOfSymbol(symbol)
  for (const sig of checker.getSignaturesOfType(type, SignatureKind.Call)) {
    const params = sig.getParameters()
    if (params.length === 1 || params[0]?.name === 'props') return checker.getTypeOfSymbol(params[0])
  }
  return undefined
}
const caliperProps = (name: string, file: string) => {
  for (const c of Object.values<any>(caliper.components)) {
    if (nm(c.displayName.replace(/ \(.*\)$/, '')) === name && realpathSync(c.filePath) === realpathSync(file)) {
      const ids = Array.isArray(c.props) ? Object.assign({}, ...c.props.map((i: string) => caliper.propSets[i])) : c.props
      return ids
    }
  }
}
const pick = (list: any[], file: string, name: string) => list.find((c) => realpathSync(c.file) === realpathSync(file) && nm(c.name) === name)?.props
for (const file of files) {
  const mod = checker.getSymbolOfSourceFile(file)
  if (!mod) continue
  for (const exported of checker.getExportsOfModule(mod)) {
    const pt = propsTypeOf(exported)
    if (!pt) continue
    const name = nm(exported.name)
    const own = checker.getPropertiesOfType(pt).filter((p: any) => p.name !== 'ref' && p.name !== 'key' && !p.declarations?.some((d: any) => String(d.path).includes('/@types/react/')))
    if (!own.length) continue
    const types = checker.getTypeOfSymbol(own)
    const cal = caliperProps(name, file)
    const rdt = pick(dump.rdt, file, name)
    const rdg = pick(dump.rdg, file, name)
    own.forEach((p: any, i: number) => {
      const k = norm(types[i])
      const v = (n: Norm | undefined): string => (n ? compare(n, k) : 'no-prop')
      const row = {
        c: cal?.[p.name] ? compare(caliperNorm(caliper.props[cal[p.name]].type), k) : 'no-prop',
        rdt: !rdt?.[p.name] ? 'no-prop' : v(rdtNorm(rdt[p.name].type)),
        rdg: !rdg?.[p.name] ? 'no-prop' : rdg[p.name].tsType ? v(rdgNorm(rdg[p.name].tsType)) : 'no-type',
      }
      console.log(`${name}.${p.name}`.padEnd(22), checker.typeToString(types[i]).slice(0, 44).padEnd(46), 'cal:', row.c.padEnd(12), 'rdt:', row.rdt.padEnd(12), 'rdg:', row.rdg)
    })
  }
}
program.dispose()
api.close()
